contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 magic) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (magic)); require(magic <= 1000000000000000000000000000000);
        require(magic > 0);
        c.seedMarket{value: magic}(magic); if (__ESBMC_reverted()) return;
        uint256 k0 = c.getMyKilo(); if (__ESBMC_reverted()) return;
        uint256 d0 = c.getMyDrugs(); if (__ESBMC_reverted()) return;
        uint256 dprod = c.DRUGS_TO_PRODUCE_1KILO(); if (__ESBMC_reverted()) return;
        c.collectDrugs(address(0)); if (__ESBMC_reverted()) return;
        uint256 k1 = c.getMyKilo(); if (__ESBMC_reverted()) return;
        assert(k1 == k0 + d0 / dprod);
    }

    receive() external payable {}
}

