// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 magic) internal {
        magic = bound(magic, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(magic > 0);
        try c.seedMarket{value: magic}(magic) {} catch { return; }
        uint256 k0;
        try c.getMyKilo() returns (uint256 __r) { k0 = __r; } catch { return; }
        uint256 d0;
        try c.getMyDrugs() returns (uint256 __r) { d0 = __r; } catch { return; }
        uint256 dprod;
        try c.DRUGS_TO_PRODUCE_1KILO() returns (uint256 __r) { dprod = __r; } catch { return; }
        try c.collectDrugs(address(0)) {} catch { return; }
        uint256 k1;
        try c.getMyKilo() returns (uint256 __r) { k1 = __r; } catch { return; }
        assertTrue(k1 == k0 + d0 / dprod);
    }

    function testFuzz_run(uint256 magic) public {
        _run(magic);
    }

    receive() external payable {}
}
